  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chat-Sauvage-(Moine).html&quot; title=&quot;Chat sauvage&quot;&gt;Chat sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Disciple-Gris-(Moine).html&quot; title=&quot;Disciple gris&quot;&gt;Disciple gris&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Duergar-(Race).html&quot; title=&quot;Les duergars&quot;&gt;Duergar&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;l&#232;ve-De-La-Pierre-(Moine).html&quot; title=&quot;&#201;l&#232;ve de la pierre&quot;&gt;&#201;l&#232;ve de la pierre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Or&#233;ade-(Race).html&quot; title=&quot;Les or&#233;ades&quot;&gt;Or&#233;ade&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Agile-(Moine).html&quot; title=&quot;Gardien agile&quot;&gt;Gardien agile&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-F&#233;lin-(Race).html&quot; title=&quot;Les hommes-f&#233;lins&quot;&gt;Homme-f&#233;lin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-&#201;coles-(Moine).html&quot; title=&quot;Ma&#238;tre des &#233;coles&quot;&gt;Ma&#238;tre des &#233;coles&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Katas-(Moine).html&quot; title=&quot;Ma&#238;tre des katas&quot;&gt;Ma&#238;tre des katas&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Manoeuvres-(Moine).html&quot; title=&quot;Ma&#238;tre des manoeuvres&quot;&gt;Ma&#238;tre des manœuvres&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Ivre-(Moine).html&quot; title=&quot;Ma&#238;tre ivre&quot;&gt;Ma&#238;tre ivre&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-&#192;-Peau-De-Fer-(Moine).html&quot; title=&quot;Moine &#224; peau de fer&quot;&gt;Moine &#224; peau de fer&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Hobgobelin-(Race).html&quot; title=&quot;Les hobgobelins&quot;&gt;Hobgobelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-De-La-Main-Qui-Gu&#233;rit-(Moine).html&quot; title=&quot;Moine de la main qui gu&#233;rit&quot;&gt; Moine de la main qui gu&#233;rit&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-De-La-Main-Vide-(Moine).html&quot; title=&quot;Moine de la main vide&quot;&gt;Moine de la main vide&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-De-La-Montagne-Sacr&#233;e-(Moine).html&quot; title=&quot;Moine de la montagne sacr&#233;e&quot;&gt;Moine de la montagne sacr&#233;e&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Des-Cimes-(Moine).html&quot; title=&quot;Moine des cimes&quot;&gt;Moine des cimes&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vanara-(Race).html&quot; title=&quot;Les vanaras&quot;&gt;Vanara&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Des-Quatre-Vents-(Moine).html&quot; title=&quot;Moine des quatre vents&quot;&gt;Moine des quatre vents&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Du-Fant&#244;me-Affam&#233;-(Moine).html&quot; title=&quot;Moine du fant&#244;me affam&#233;&quot;&gt; Moine du fant&#244;me affam&#233;&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Du-Lotus-(Moine).html&quot; title=&quot;Moine du lotus&quot;&gt;Moine du lotus&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Fluide-(Moine).html&quot; title=&quot;Moine fluide&quot;&gt;Moine fluide&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Karmique-(Moine).html&quot; title=&quot;Moine karmique&quot;&gt;Moine karmique&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Qinggong-(Moine).html&quot; title=&quot;Moine qinggong&quot;&gt;Moine qinggong&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mystique-Ki-(Moine).html&quot; title=&quot;Mystique ki&quot;&gt;Mystique ki&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Conseiller-(Moine).html&quot; title=&quot;Sage conseiller&quot;&gt;Sage conseiller&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sensei-(Moine).html&quot; title=&quot;Sensei&quot;&gt;Sensei&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sohei-(Moine).html&quot; title=&quot;Sohei&quot;&gt;Sohei&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tetori-(Moine).html&quot; title=&quot;Tetori&quot;&gt;Tetori&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vagabond-(Moine).html&quot; title=&quot;Vagabond&quot;&gt;Vagabond&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;) (MR)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la magie (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Magic/Art de la Magie&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUM.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;
&lt;i&gt;Le moine qinggong est un ma&#238;tre du ki qu’il utilise pour accomplir des acrobaties surhumaines ou pour frapper ses adversaires avec une d&#233;charge d’&#233;nergie surnaturelle. Certains obtiennent une telle ma&#238;trise du ki gr&#226;ce &#224; une discipline extr&#234;me, d’autres en ing&#233;rant (intentionnellement ou non) des herbes rares et d’&#233;tranges fruits mystiques tandis que quelques rares individus obtiennent leurs pouvoirs d’un ma&#238;tre qinggong mourant.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pouvoirs de ki&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoirs_de_ki_0&quot; href=&quot;#Pouvoirs_de_ki_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Lart-De-La-Magie.html#27&quot; title=&quot;FAQ de l&amp;#39;Art de la magie&quot;&gt;→&lt;/a&gt; Moine : Un moine qinggong peut-il s&#233;lectionner un second arch&#233;type si le personnage ne remplace pas les capacit&#233;s modifi&#233;es par ce second arch&#233;type ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Oui. Cependant, l&#39;autre arch&#233;type a la priorit&#233; sur les diverses capacit&#233;s offertes &#224; chaque niveau, et le personnage ne peut pas retarder l&#39;obtention d&#39;une capacit&#233; que l&#39;autre arch&#233;type remplace ; il doit laisser le second arch&#233;type remplacer la capacit&#233; pr&#233;vue au niveau de classe pr&#233;vu.&lt;br /&gt;&lt;br /&gt;Par exemple, l&#39;arch&#233;type &lt;a class=&quot;pagelink&quot; href=&quot;Moine-De-La-Main-Qui-Gu&#233;rit-(Moine).html&quot; title=&quot;Moine de la main qui gu&#233;rit&quot;&gt;moine de la main qui gu&#233;rit&lt;/a&gt; remplace  
pl&#233;nitude physique (niveau 7)  
corps de diamant (niveau 11)  
paume vibratoire (niveau 15)  
perception de l&#39;&#234;tre (niveau 20).  
Un &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Qinggong-(Moine).html&quot; title=&quot;Moine qinggong&quot;&gt;moine qinggong&lt;/a&gt;&lt;/u&gt; qui souhaite &#233;galement choisir l&#39;arch&#233;type moine de la main qui gu&#233;rit doit laisser l&#39;arch&#233;type de la main qui gu&#233;rit remplacer chacune de ces quatre capacit&#233;s aux niveaux pr&#233;vus. Le moine qinggong est toujours libre de remplacer n&#39;importe quelle capacit&#233; de moine standard aux autres niveaux list&#233;s dans l&#39;arch&#233;type moine qinggong (chute ralentie au niveau 4, sauts puissants au niveau 5, etc), tant que s&#233;lectionner ces capacit&#233;s n&#39;interf&#232;re pas avec l&#39;obtention des capacit&#233;s de moine de la main qui gu&#233;rit aux niveaux pr&#233;vus.  
Notez que si le second arch&#233;type remplace une capacit&#233; de moine standard, le personnage ne peut pas s&#233;lectionner la capacit&#233; remplac&#233;e &#224; un niveau de moine ult&#233;rieur. Par exemple, le moine qinggong/de la main qui gu&#233;rit ne peut jamais s&#233;lectionner pl&#233;nitude physique, m&#234;me apr&#232;s le niveau 7. Dans les faits, le personnage a s&#233;lectionn&#233; pl&#233;nitude physique au niveau 7 et l&#39;a imm&#233;diatement remplac&#233; par une capacit&#233; de la main qui gu&#233;rit ; &#233;tant donn&#233; que l&#39;arch&#233;type qinggong ne permet &#224; un personnage de s&#233;lectionner une capacit&#233; plus tard que s&#39;il a &#171; choisit un pouvoir de ki diff&#233;rent &#224; la place du pouvoir habituel &#187; (ce qui n&#39;est pas arriv&#233;), cette option n&#39;est pas accessible &#224; ce personnage.
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;Un moine qinggong peut choisir un pouvoir de ki pour lequel il remplit les conditions requises &#224; la place de l’un des pouvoirs de moine suivants : &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#CHUTERALENTIE&quot; title=&quot;Le moine&quot;&gt;chute ralentie&lt;/a&gt; (4), &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#SAUTSPUISSANTS&quot; title=&quot;Le moine&quot;&gt;sauts puissants&lt;/a&gt; (5), &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#PLENITUDEPHYSIQUE&quot; title=&quot;Le moine&quot;&gt;pl&#233;nitude physique&lt;/a&gt; (7), &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#CORPSDEDIAMANT&quot; title=&quot;Le moine&quot;&gt;corps de diamant&lt;/a&gt; (11), &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#PASCHASSE&quot; title=&quot;Le moine&quot;&gt;pas chass&#233;&lt;/a&gt; (12), &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#AMEDEDIAMANT&quot; title=&quot;Le moine&quot;&gt;&#226;me de diamant&lt;/a&gt; (13), &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#PAUMEVIBRATOIRE&quot; title=&quot;Le moine&quot;&gt;paume vibratoire&lt;/a&gt; (15), &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#ETERNELLEJEUNESSE&quot; title=&quot;Le moine&quot;&gt;&#233;ternelle jeunesse&lt;/a&gt; (17), &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#LANGAGEDUSOLEILETDELALUNE&quot; title=&quot;Le moine&quot;&gt;langage du soleil et de la lune&lt;/a&gt; (17), &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#DESERTIONDELAME&quot; title=&quot;Le moine&quot;&gt;d&#233;sertion de l’&#226;me&lt;/a&gt; (19) et &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#PERFECTIONDELETRE&quot; title=&quot;Le moine&quot;&gt;perfection de l’&#234;tre&lt;/a&gt; (20). Ce pouvoir remplace celui auquel le moine a renonc&#233; pour choisir le &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Ki.html&quot; title=&quot;Les pouvoirs de ki&quot;&gt;pouvoir de ki&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;table id=&quot;TocContainerTable&quot;&gt;&lt;tr&gt;&lt;td&gt;&lt;div id=&quot;TocContainer&quot;&gt;&lt;p class=&quot;small&quot;&gt;&lt;b&gt;Table of Contents&lt;/b&gt;&lt;span id=&quot;ExpandTocSpan&quot;&gt; [&lt;a href=&quot;#&quot; onclick=&quot;javascript:if(document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]==&#39;none&#39;) document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;&#39;; else document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;none&#39;; return false;&quot;&gt;Hide/Show&lt;/a&gt;]&lt;/span&gt;&lt;/p&gt;&lt;div id=&quot;Toc&quot;&gt;&lt;p&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_ki_0&quot;&gt;Pouvoirs de ki&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_ki_de_niveau_E_1&quot;&gt;Pouvoirs de ki de niveau 4&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_ki_de_niveau_G_2&quot;&gt;Pouvoirs de ki de niveau 6&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_ki_de_niveau_I_3&quot;&gt;Pouvoirs de ki de niveau 8&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_ki_de_niveau_BA_4&quot;&gt;Pouvoirs de ki de niveau 10&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_ki_de_niveau_BC_5&quot;&gt;Pouvoirs de ki de niveau 12&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_ki_de_niveau_BE_6&quot;&gt;Pouvoirs de ki de niveau 14&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_ki_de_niveau_BG_7&quot;&gt;Pouvoirs de ki de niveau 16&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_ki_de_niveau_BI_8&quot;&gt;Pouvoirs de ki de niveau 18&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pouvoirs_de_ki_de_niveau_CA_9&quot;&gt;Pouvoirs de ki de niveau 20&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;i&gt;Les pouvoirs de ki puisent dans le ki du moine. La classe de base de &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; poss&#232;de plusieurs pouvoirs de ce type, comme pl&#233;nitude physique, pas chass&#233; et d&#233;sertion de l’&#226;me. Le moine qinggong peut en apprendre d’autres qui viennent souvent remplacer un pouvoir sans lien avec le ki comme la puret&#233; physique.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Les pouvoirs de ki se divisent en trois cat&#233;gories : les dons, les pouvoirs de moine et les sorts.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Les dons.&lt;/i&gt; Ces pouvoirs de ki reproduisent les effets d’un don sp&#233;cifique. Le &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; n’a pas besoin de remplir les conditions requises par le don pour choisir le pouvoir de ki correspondant. Par exemple, un moine qinggong peut choisir Attaque &#233;clair comme pouvoir de ki m&#234;me s’il ne remplit pas les conditions requises pour choisir ce don. Le &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; active un pouvoir de ki &#224; son tour, par une action libre. On consid&#232;re qu’il dispose alors du don choisi jusqu’&#224; son prochain tour. Certains pouvoirs de ki qui imitent un don s’activent par une action imm&#233;diate, ce qui est indiqu&#233; dans la liste des pouvoirs de ki.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Les pouvoirs de moine.&lt;/i&gt; Certains pouvoirs de ki sont des pouvoirs de &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; ordinaire du Manuel des Joueurs. M&#234;me si le moine qinggong choisit un pouvoir de ki diff&#233;rent &#224; la place du pouvoir habituel, il peut le choisir plus tard, comme un pouvoir de ki.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Les sorts.&lt;/i&gt; Ces pouvoirs de ki reproduisent les effets d’un sort ou d’un pouvoir magique. Le &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; utilise son niveau de classe comme niveau de lanceur de sorts et sa Sagesse pour d&#233;terminer le bonus aux tests de concentration.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Conditions requises.&lt;/b&gt; Tous les pouvoirs de ki exigent un niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; minimum. Tant que le &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; ne l’a pas atteint, il ne peut pas choisir le pouvoir.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Activation.&lt;/b&gt; La plupart des pouvoirs de ki n&#233;cessitent une d&#233;pense en point de ki. Ceux qui demandent 0 point peuvent &#234;tre utilis&#233;s m&#234;me si le &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; n’a plus le moindre point de ki dans sa r&#233;serve.&lt;br /&gt;&lt;br /&gt;Le &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; contre les pouvoirs de ki de &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; est &#233;gal &#224; 10 +1/2 niveau du moine + bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;Les dons marqu&#233;s d’une croix (†) sont des pouvoirs de ki qui s’activent par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;1&quot; href=&quot;#1&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Pouvoirs de ki de niveau 4&lt;a class=&quot;headeranchor&quot; id=&quot;Pouvoirs_de_ki_de_niveau_E_1&quot; href=&quot;#Pouvoirs_de_ki_de_niveau_E_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arme-En-Main.html&quot; title=&quot;Arme en main&quot;&gt;Arme en main&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; (1 point de ki)&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Puissance.html&quot; title=&quot;Attaque en puissance&quot;&gt;Attaque en puissance&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; (1 point de ki)&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Augure.html&quot; title=&quot;Augure&quot;&gt;Augure&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; (1 point de ki)&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#CHUTERALENTIE&quot; title=&quot;Le moine&quot;&gt;Chute ralentie&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; (pouvoir de &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt;, 0 point de ki)&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Coup-Au-But.html&quot; title=&quot;Coup au but&quot;&gt;Coup au but&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; (sur soi uniquement, 1 point de ki)&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;marche-A&#233;rienne.html&quot; title=&quot;D&#233;marche a&#233;rienne&quot;&gt;D&#233;marche a&#233;rienne&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; (&lt;b&gt;APG&lt;/b&gt;) (sur soi uniquement, 1 point de ki)&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;placement-Acrobatique.html&quot; title=&quot;D&#233;placement acrobatique&quot;&gt;D&#233;placement acrobatique&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; (1 point de ki)&lt;/li&gt;&lt;li&gt